// Vercel Routing Middleware: serve Markdown to agents that ask for it.
// Requests with "Accept: text/markdown" receive the Markdown twin of the page
// from /md/<path>.md (generated by _build/build.py); missing pages get a
// Markdown 404 body with the correct status.
export const config = { matcher: '/((?!assets/|md/|.*\.(?:xml|txt|ico|png|jpg|webp|css|js)$).*)' };

export default async function middleware(request) {
  const accept = request.headers.get('accept') || '';
  if (!accept.includes('text/markdown')) return;
  const url = new URL(request.url);
  const path = url.pathname.replace(/\/+$/, '');
  const mdPath = path === '' ? '/md/index.md' : `/md${path}.md`;
  const res = await fetch(new URL(mdPath, url.origin));
  if (res.ok) {
    return new Response(await res.text(), {
      status: 200,
      headers: { 'content-type': 'text/markdown; charset=utf-8', 'vary': 'Accept', 'x-robots-tag': 'noindex', 'link': `<${url.origin}${path || '/'}>; rel="canonical"` },
    });
  }
  const body = `# Page not found\n\nThere is no page at \`${url.pathname}\` on centerpointmgmt.com.\n\n- [Home](${url.origin}/)\n- [Services](${url.origin}/services)\n- [Board guides](${url.origin}/blog)\n- [Service areas](${url.origin}/service-areas)\n- [Site index for AI assistants](${url.origin}/llms.txt)\n`;
  return new Response(body, { status: 404, headers: { 'content-type': 'text/markdown; charset=utf-8', 'vary': 'Accept' } });
}
